/* @lc app=leetcode id=4064 lang=kotlin */ class Solution { fun longestSubarray(nums: IntArray, k: Int): Int = (if (k % 2 == 1) k else k / 2).let { half -> nums.runningFold(0) { a, b -> ((a + b) % k + k) % k }.let { P -> IntArray(k) { if (it == 0) 0 else Int.MAX_VALUE }.also { fp -> (1..nums.size).forEach { fp[P[it]] = minOf(fp[P[it]], it) } }.let { fp -> (0 until k).filter { fp[it] != Int.MAX_VALUE }.sortedBy { fp[it] }.toIntArray().let { order -> IntArray(half).let { ptr -> IntArray(k) { Int.MAX_VALUE }.let { best -> nums.indices.maxOf { i -> ((nums[i] % half + half) % half).let { v -> generateSequence(ptr[v]) { it + 1 }.takeWhile { p -> p < order.size && fp[order[p]] <= i }.forEach { p -> best.set((order[p] + 2 * v) % k, minOf(best[(order[p] + 2 * v) % k], fp[order[p]])).also { ptr[v] = p + 1 } }.let { maxOf(i + 1 - fp[P[i + 1]], i + 1 - best[P[i + 1]]) } } } } } } } } } }